  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Fimasartan, the closest analogue (Morgan 0.2604), has an absolute oral bioavailability of 18.6% in healthy volunteers after a 60-mg oral tablet vs 30-mg IV infusion, falling below the 20% threshold; its ARB-like imidazole/butyl/benzyl scaffold and acidic tetrazole support a low-F outcome for the similarly acidic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Telmisartan, an ARB with a carboxylic acid and benzimidazole, has an absolute oral bioavailability of 43% in healthy subjects, demonstrating that some ARB-like acids exceed 20%; however, it is more lipophilic and has only one ionizable acid, limiting transfer to the dianionic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C43"],
      "claim": "Irbesartan, an ARB with imidazole/butyl and biphenyl-tetrazole, has an average absolute oral bioavailability of 60-80% in humans, showing the ARB scaffold can be well absorbed; its lack of a carboxylic acid and higher lipophilicity make it less transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Bumetanide, a carboxylic acid-containing drug with sulfonamide and phenoxy groups, has an absolute oral bioavailability of 0.79 ± 0.12 in elderly subjects, indicating that ionizable acids can be well absorbed; it has only one carboxylic acid and a different scaffold, so it is a weaker counterexample.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low. The closest structural analogue, fimasartan, has absolute oral bioavailability 18.6% in humans, just below the 20% threshold, and shares the ARB-like imidazole/butyl/benzyl scaffold and an acidic ionizable group. The query is even more polar (two carboxylic acids, dianion at pH 7.4, logD 0.56), which would be expected to further reduce permeability and absorption. Numerous high-F analogues are less similar, generally more lipophilic, or contain only one acid or a prodrug, so they do not override the closest low-F evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to all evidence molecules are low (<0.26), limiting transferability.",
    "No data on active transport, efflux, or formulation effects for the query.",
    "Fimasartan is just below the threshold; small structural differences could change the binary call."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

